// RToken Oracle Interface
interface IRTokenOracle {
    struct CachedOracleData {
        uint192 cachedPrice; // {UoA/tok}
        uint256 cachedAtTime; // {s}
        uint48 cachedAtNonce; // {basketNonce}
        uint48 cachedTradesOpen;
